#[cfg(feature = "serde_enabled")]
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;
use std::path::PathBuf;
use std::process::{Command, Stdio};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

#[cfg(feature = "hex_enabled")]
use hex::encode;
#[cfg(feature = "sha1_enabled")]
use sha1::Digest;
#[cfg(feature = "walkdir_enabled")]
use walkdir::WalkDir;

// Include the tests generated by build.rs (now just a placeholder)
include!(concat!(env!("OUT_DIR"), "/generated_tests.rs"));

const REPORT_FILE: &str = "feature_permutation_report.json";
const CACHE_FILE: &str = "feature_permutation_cache.json";
const GIT_WRAPPER_LIB_PATH: &str = "tools/git-wrapper-lib";

#[derive(Debug, Default, Clone)]
#[cfg_attr(feature = "serde_enabled", derive(Serialize, Deserialize))]
struct BuildResult {
    feature_set: String,
    status: String,
    build_time_ms: Option<u128>,
    binary_size_bytes: Option<u64>,
    error_message: Option<String>,
    source_hash: String,
    timestamp: u64,
}

#[derive(Debug, Default, Clone)]
#[cfg_attr(feature = "serde_enabled", derive(Serialize, Deserialize))]
struct BuildCache {
    results: HashMap<String, BuildResult>,
}

fn calculate_source_hash(feature_set: &str) -> Result<String, Box<dyn std::error::Error>> {
    #[cfg(feature = "sha1_enabled")]
    let mut hasher = sha1::Sha1::new();
    #[cfg(not(feature = "sha1_enabled"))]
    let mut hasher = DummyHasher::new(); // Placeholder if sha1 is not enabled

    let git_wrapper_lib_path = PathBuf::from(GIT_WRAPPER_LIB_PATH);

    // Hash Cargo.toml
    let cargo_toml_content = fs::read(&git_wrapper_lib_path.join("Cargo.toml"))?;
    hasher.update(&cargo_toml_content);

    // Hash src directory
    #[cfg(feature = "walkdir_enabled")]
    for entry in walkdir::WalkDir::new(&git_wrapper_lib_path.join("src")) {
        let entry = entry?;
        if entry.file_type().is_file() {
            let content = fs::read(entry.path())?;
            hasher.update(&content);
        }
    }

    // Incorporate feature set into the hash
    hasher.update(feature_set.as_bytes());

    #[cfg(feature = "hex_enabled")]
    return Ok(hex::encode(hasher.finalize()));
    #[cfg(not(feature = "hex_enabled"))]
    return Ok(format!("{:?}", hasher.finalize())); // Placeholder if hex is not enabled
}

#[cfg(not(feature = "sha1_enabled"))]
struct DummyHasher;

#[cfg(not(feature = "sha1_enabled"))]
impl DummyHasher {
    fn new() -> Self {
        DummyHasher
    }
    fn update(&mut self, _data: &[u8]) {}
    fn finalize(&self) -> [u8; 20] {
        [0; 20]
    } // Dummy hash
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("Feature Permutation Builder: Starting tests...");

    #[cfg(feature = "serde_enabled")]
    let mut build_cache = load_build_cache()?;
    #[cfg(not(feature = "serde_enabled"))]
    let mut build_cache = BuildCache::default(); // Dummy cache if serde is not enabled

    let mut current_run_results: Vec<BuildResult> = Vec::new();

    let features_to_test = vec![
        "", // No features
        "git2",
        "with-anyhow",
        "with-trace",
        "git2,with-anyhow",
        "git2,with-trace",
        "with-anyhow,with-trace",
        "git2,with-anyhow,with-trace",
    ];

    for feature_set in features_to_test {
        println!("\n--- Testing feature set: '{}' ---", feature_set);

        let current_source_hash = calculate_source_hash(feature_set)?;
        let should_build = true;
        let mut build_time_ms = None;
        let mut binary_size_bytes = None;
        let mut error_message = None;
        let timestamp = SystemTime::now().duration_since(UNIX_EPOCH)?.as_secs();

        #[cfg(feature = "serde_enabled")]
        if let Some(cached_result) = build_cache.results.get(feature_set) {
            if cached_result.source_hash == current_source_hash && cached_result.status == "SUCCESS"
            {
                println!("Skipping build for '{}' - source hash matches and previous build was successful.", feature_set);
                should_build = false;
                build_time_ms = cached_result.build_time_ms;
                binary_size_bytes = cached_result.binary_size_bytes;
            } else if cached_result.source_hash == current_source_hash
                && cached_result.status == "FAILED"
            {
                println!(
                    "Re-running build for '{}' - source hash matches but previous build failed.",
                    feature_set
                );
                should_build = true; // Force rerun if previous failed
            } else {
                println!(
                    "Re-running build for '{}' - source hash changed.",
                    feature_set
                );
                should_build = true;
            }
        }

        let mut status = "SKIPPED".to_string();

        if should_build {
            let start_time = Instant::now();

            let mut command = Command::new("cargo");
            command
                .arg("build")
                .arg("-p")
                .arg("git-wrapper-lib")
                .arg("--release"); // Use release profile for more realistic timing

            if !feature_set.is_empty() {
                command.arg("--features").arg(feature_set);
            }

            let output = command
                .stdout(Stdio::inherit())
                .stderr(Stdio::inherit())
                .output()?;

            let duration = start_time.elapsed();
            build_time_ms = Some(duration.as_millis());

            if output.status.success() {
                println!("Build successful in {:?}", duration);
                status = "SUCCESS".to_string();

                // Try to get binary size
                let target_dir = PathBuf::from(
                    std::env::var("CARGO_TARGET_DIR").unwrap_or_else(|_| "target".to_string()),
                );
                let binary_path = target_dir.join("release").join("git-wrapper-lib"); // Assuming it's a lib, not an executable
                if binary_path.exists() {
                    if let Ok(metadata) = fs::metadata(&binary_path) {
                        binary_size_bytes = Some(metadata.len());
                    }
                }
            } else {
                eprintln!("Build failed in {:?}", duration);
                eprintln!("Error: {:?}", output.status);
                status = "FAILED".to_string();
                error_message = Some(String::from_utf8_lossy(&output.stderr).to_string());
            }
        }

        let result = BuildResult {
            feature_set: feature_set.to_string(),
            status,
            build_time_ms,
            binary_size_bytes,
            error_message,
            source_hash: current_source_hash,
            timestamp,
        };
        build_cache
            .results
            .insert(feature_set.to_string(), result.clone());
        current_run_results.push(result);
    }

    #[cfg(feature = "serde_enabled")]
    save_build_cache(&build_cache)?;
    #[cfg(feature = "serde_enabled")]
    generate_report(&current_run_results)?;

    println!("\nFeature Permutation Builder: All tests completed.");
    Ok(())
}

#[cfg(feature = "serde_enabled")]
fn load_build_cache() -> Result<BuildCache, Box<dyn std::error::Error>> {
    if Path::new(CACHE_FILE).exists() {
        let content = fs::read_to_string(CACHE_FILE)?;
        Ok(serde_json::from_str(&content)?)
    } else {
        Ok(BuildCache::default())
    }
}

#[cfg(not(feature = "serde_enabled"))]
fn load_build_cache() -> Result<BuildCache, Box<dyn std::error::Error>> {
    Ok(BuildCache::default())
}

#[cfg(feature = "serde_enabled")]
fn save_build_cache(cache: &BuildCache) -> Result<(), Box<dyn std::error::Error>> {
    let content = serde_json::to_string_pretty(cache)?;
    fs::write(CACHE_FILE, content)?;
    Ok(())
}

#[cfg(not(feature = "serde_enabled"))]
fn save_build_cache(_cache: &BuildCache) -> Result<(), Box<dyn std::error::Error>> {
    Ok(())
}

#[cfg(feature = "serde_enabled")]
fn generate_report(results: &[BuildResult]) -> Result<(), Box<dyn std::error::Error>> {
    let content = serde_json::to_string_pretty(results)?;
    fs::write(REPORT_FILE, content)?;
    println!("\nGenerated report: {}", REPORT_FILE);
    Ok(())
}

#[cfg(not(feature = "serde_enabled"))]
fn generate_report(_results: &[BuildResult]) -> Result<(), Box<dyn std::error::Error>> {
    Ok(())
}
